  add('motivate', '도입', { scene_title: t.mot.t, desc: t.mot.desc, question: t.mot.q, img: 'assets/photo/math/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
